use soroban_sdk::contracttype;
use sororail_common::impl_single_position_storage;

use crate::types::Escrow;

/// Storage keys for the escrow contract.
///
/// Every value lives in **instance** storage, so the whole agreement shares
/// one TTL with the contract. The enum has a single variant because one
/// instance holds one agreement. It is still a `#[contracttype]` enum rather
/// than a raw symbol so the key is typed, and so a second key can be added
/// later without changing how existing keys encode.
///
/// Access goes through the helpers generated by
/// `impl_single_position_storage!`, which extend the TTL on every write.
#[contracttype]
pub enum DataKey {
    /// The single escrow agreement held by this instance. First written by
    /// `init`, then updated in place by every state-changing entry point
    /// that touches the agreement (`cancel`, `fund`, `release`, `refund`,
    /// `dispute`, `resolve`).
    ///
    /// Holds the full [`Escrow`] record, including its [`State`]. Absent
    /// until `init` runs, which is what `NotInitialized` reports.
    ///
    /// [`State`]: crate::types::State
    Escrow,
}

impl_single_position_storage!(Escrow, DataKey::Escrow);
